-- GymTrack USAG AI deduction rules
-- Run after supabase/ai_judge_schema.sql. It creates the editable rule engine used by /ai-judge.
create table if not exists usag_deduction_rules (
  id text primary key,
  level_name text not null,
  apparatus text not null,
  element_name text not null,
  textbook_fault text not null,
  deduction_min numeric not null default 0.05,
  deduction_max numeric not null default 0.30,
  default_value numeric not null default 0.10,
  measurement_target text,
  correction_focus text,
  source_note text,
  created_at timestamptz not null default now()
);
alter table usag_deduction_rules enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='usag_deduction_rules' and policyname='authenticated read usag deduction rules') then
    create policy "authenticated read usag deduction rules" on usag_deduction_rules for select to authenticated using (true);
  end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='usag_deduction_rules' and policyname='authenticated manage usag deduction rules') then
    create policy "authenticated manage usag deduction rules" on usag_deduction_rules for all to authenticated using (true) with check (true);
  end if;
end $$;

on conflict (id) do update set level_name=excluded.level_name, apparatus=excluded.apparatus, element_name=excluded.element_name, textbook_fault=excluded.textbook_fault, deduction_min=excluded.deduction_min, deduction_max=excluded.deduction_max, default_value=excluded.default_value, measurement_target=excluded.measurement_target, correction_focus=excluded.correction_focus, source_note=excluded.source_note;